const results = [];
for (const item of items) {
  const binaryKeys = Object.keys(item.binary || {});
  const attachmentKeys = binaryKeys.filter(k => k.startsWith('attachment_'));
  // No attachments at all -> skip this email entirely, don't log anywhere
  if (attachmentKeys.length === 0) {
    continue;
  }
  for (const key of attachmentKeys) {
    results.push({
      json: item.json,
      binary: { data: item.binary[key] }
    });
  }
}
return results;
